- fn redact (stella-observatory/src/fsview.rs:496)
  fn redact(value: &mut Value, in_credential_scope: bool) {
      match value {
          Value::Object(map) => {
              for (key, v) in map.iter_mut() {
                  let scoped = in_credential_scope
                      || sensitive_key(key)
                      || matches!(key.as_str(), "env" | "headers");
                  if scoped && v.is_string() {
                      *v = Value::String("<redacted>".into());
                  } else {
                      redact(v, scoped);
                  }
              }
          }
          Value::Array(items) => {
              for item in items.iter_mut() {
                  if in_credential_scope && item.is_string() {
                      *item = Value::String("<redacted>".into());
                  } else {
                      redact(item, in_credential_scope);
                  }
              }
          }
          _ => {}
      }
  }
- fn redact (stella-pipeline/src/witness/airlock.rs:562)
  pub fn redact(sealed: &SealedFailure<'_>, requested: DisclosureGrain) -> FailureBrief {
      let mut grain = requested;

      let reproduction = if grain >= DisclosureGrain::Reproduction {
          let candidate = format!("`{}`", sealed.command);
          match scrub(&candidate, sealed) {
              Ok(()) => Some(candidate),
              Err(_) => {
                  grain = DisclosureGrain::Symptom;
                  None
              }
          }
      } else {
          None
      };

      let symptom = (grain >= DisclosureGrain::Symptom).then(|| sealed.symptom());

      let command = if grain >= DisclosureGrain::Command {
          let candidate = sealed.command.to_string();
          match scrub(&candidate, sealed) {
              Ok(()) => Some(candidate),
              Err(_) => {
                  grain = DisclosureGrain::Outcome;
                  None
              }
          }
      } else {
          None
      };

      FailureBrief {
          grain,
          // A grain that fell to `Outcome` withholds the command it could not
          // scrub; one that merely lost its reproduction keeps it.
          command: (grain >= DisclosureGrain::Command)
              .then_some(command)
              .flatten(),
          symptom: (grain >= DisclosureGrain::Symptom)
              .then_some(symptom)
              .flatten(),
          // Gated by the *final* grain like its siblings, not just the branch
          // that built it. `reproduction` can only be `Some` when the command
          // scrubbed clean (the reproduction candidate is a superset of the bare
          // command, so it scrubs strictly harder), which means `grain` never
          // fell below `Reproduction` here — the guard is a no-op today. It exists
          // so a future change to the reproduction candidate can never leave a
          // brief reporting a low grain while still carrying a reproduction.
          reproduction: (grain >= DisclosureGrain::Reproduction)
              .then_some(reproduction)
              .flatten(),
      }
  }

